import assert from 'assert';

import Joi from 'joi';

import { BaseException, JoiValidationException, ValidationException } from '../../index';
import constants from '../../lib/utils/constants';

describe('JoiValidationException', function () {
  it('maps a single Joi ValidationError detail to serializeErrors()', function () {
    const schema = Joi.object({
      email: Joi.string().email().required(),
    });
    const { error } = schema.validate({ email: 'not-an-email' });
    assert.ok(error);

    const err = new JoiValidationException(error);
    const expected = error.details.map((d) => ({ message: d.message }));

    assert.deepStrictEqual(err.serializeErrors(), expected);
    assert.strictEqual(err.serializeErrors().length, 1);
    assert.strictEqual(err.serializeErrors()[0].message, error.details[0].message);
  });

  it('maps multiple Joi details in order when abortEarly is false', function () {
    const schema = Joi.object({
      a: Joi.string().required(),
      b: Joi.number().required(),
    });
    const { error } = schema.validate({}, { abortEarly: false });
    assert.ok(error);

    const err = new JoiValidationException(error);
    const expected = error.details.map((d) => ({ message: d.message }));

    assert.deepStrictEqual(err.serializeErrors(), expected);
    assert.ok(err.serializeErrors().length >= 2);
  });

  it('returns an empty array when details is empty (mock; Joi does not emit this)', function () {
    const err = new JoiValidationException({ details: [] });

    assert.deepStrictEqual(err.serializeErrors(), []);
  });

  it('exposes status code 400 and ValidationException / Error inheritance', function () {
    const schema = Joi.string().min(5);
    const { error } = schema.validate('hi');
    assert.ok(error);

    const err = new JoiValidationException(error);

    assert.strictEqual(err.statusCode, constants.HTTP_STATUS_CODES.BAD_REQUEST);
    assert.ok(err instanceof JoiValidationException);
    assert.ok(err instanceof ValidationException);
    assert.ok(err instanceof BaseException);
    assert.ok(err instanceof Error);
    assert.strictEqual(Object.getPrototypeOf(err), JoiValidationException.prototype);
  });

  it('sets the Error message from ValidationException', function () {
    const schema = Joi.boolean();
    const { error } = schema.validate('not-a-boolean');
    assert.ok(error);

    const err = new JoiValidationException(error);

    assert.strictEqual(err.message, 'Validation Errors');
  });

  describe('invalid input', function () {
    it('throws when errors is undefined', function () {
      assert.throws(
        () => new JoiValidationException(undefined as unknown as { details: unknown }),
        TypeError,
      );
    });

    it('throws when details is missing', function () {
      assert.throws(() => new JoiValidationException({} as { details: unknown[] }), TypeError);
    });
  });
});

import expressExceptionHandler from './lib/exceptions/express-exception-middleware';
import exceptionMapper from './lib/exceptions/exception-mapper';
import { BadRequestException } from './lib/exceptions/bad-request-exception';
import { BaseException } from './lib/exceptions/base-exception';
import { NotFoundException } from './lib/exceptions/not-found-exception';
import { UnauthorizedException } from './lib/exceptions/unauthorized-exception';
import { ForbiddenException } from './lib/exceptions/forbidden-exception';
import { ValidationException } from './lib/exceptions/validation-exception';
import { ServerException } from './lib/exceptions/server-exception';
import { JoiValidationException } from './lib/common-exceptions/joi-validation-exception';
import { ZodValidationException } from './lib/common-exceptions/zod-validation-exception';
import { SQLDatabaseException } from './lib/db-exceptions/exceptions/sql-exceptions/sql-database-exception';
import ILogger from './lib/logger/logger.interface';
import { IException } from './lib/exceptions/interfaces/exception.interface';
import { NoSQLDatabaseException } from './lib/db-exceptions/exceptions/no-sql-exceptions/no-sql-database-exception';
import { DatabaseException } from './lib/db-exceptions/exceptions/database-exception';
import { IExceptionMapperOptions } from './lib/exceptions/interfaces/exception.interface';

export {
  expressExceptionHandler,
  exceptionMapper,
  BadRequestException,
  NoSQLDatabaseException,
  DatabaseException,
  BaseException,
  NotFoundException,
  ValidationException,
  ServerException,
  JoiValidationException,
  ZodValidationException,
  UnauthorizedException,
  ForbiddenException,
  SQLDatabaseException,
  ILogger,
  IException,
  IExceptionMapperOptions,
};

import { BaseException } from './base-exception';
import exceptionMapper from './exception-mapper';
import { IExceptionMapperOptions } from './interfaces/exception.interface';

export default function expressExceptionHandler(options?: IExceptionMapperOptions) {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  return (err: Error, req: any, res: any, next: any) => {
    if (err instanceof BaseException) {
      return res.status(err.statusCode).send({ errors: err.serializeErrors() });
    }

    const mappedError = exceptionMapper(err, options);

    return res.status(mappedError.statusCode).send({
      errors: mappedError.serializeErrors(),
    });
  };
}

import { IException } from './interfaces/exception.interface';

export abstract class BaseException extends Error {
  abstract statusCode: number;

  constructor(message: string) {
    super(message);

    Object.setPrototypeOf(this, BaseException.prototype);
  }

  abstract serializeErrors(): IException[];
}

import { DBError } from 'db-errors';
import { BaseException } from './base-exception';
import { IExceptionMapperOptions } from './interfaces/exception.interface';
import { ServerException } from './server-exception';
import sequelizeDBExceptionParser, { isSequelizeError } from '../db-exceptions/sequelize-parser';
import objectionDBExceptionParser from '../db-exceptions/objectionjs-parser';
import typeormDBExceptionParser, { isTypeORMError } from '../db-exceptions/typeorm-parser';
import mongoDBExceptionParser, { isMongoDBError, isMongooseDBError } from '../db-exceptions/mongodb-parser';
import log from '../logger/logger';

function dbExceptionMapper(error: unknown, options?: IExceptionMapperOptions): BaseException | null {
  if (options?.parseMongooseExceptions && (isMongoDBError(error) || isMongooseDBError(error))) {
    return mongoDBExceptionParser(error);
  } else if (options?.parseSequelizeExceptions && isSequelizeError(error)) {
    return sequelizeDBExceptionParser(error);
  } else if (options?.parseTypeORMExceptions && isTypeORMError(error)) {
    return typeormDBExceptionParser(error);
  } else if ((options?.parseObjectionJSExceptions && error instanceof DBError) || options?.parseKnexJSExceptions) {
    return objectionDBExceptionParser(error);
  } else if (
    options?.parseSequelizeExceptions ||
    options?.parseObjectionJSExceptions ||
    options?.parseTypeORMExceptions ||
    options?.parseKnexJSExceptions
  ) {
    return objectionDBExceptionParser(error);
  }
  return null;
}

export default function exceptionMapper(err: unknown, options?: IExceptionMapperOptions): BaseException {
  if (options?.loggerOptions) {
    log(err, options?.loggerOptions);
  }
  if (options?.mapDBExceptions) {
    throw new Error(
      `mapDBExceptions is deprecated.\n
      please use other options :\n
      \t - parseMongooseExceptions to parse mongoose errors.\n
      \t - parseSequelizeExceptions to parse Sequelize errors.\n
      \t - parseTypeORMExceptions to parse TypeORM errors.\n
      \t - parseObjectionJSExceptions to parse ObjectionJS errors.\n
      \t - parseKnexJSExceptions to parse KnexJS errors.\n
      For more info visit https://github.com/AhmedAdelFahim/unified-errors-handler`,
    );
  }
  const mappedError = dbExceptionMapper(err, options);
  if (mappedError) {
    return mappedError;
  }
  if (err instanceof BaseException) {
    return err;
  }
  return new ServerException();
}

import constants from '../utils/constants';
import { BaseException } from './base-exception';
import { IException } from './interfaces/exception.interface';

export class ServerException extends BaseException {
  statusCode = constants.HTTP_STATUS_CODES.INTERNAL_SERVER_ERROR;

  constructor(
    public error: IException = { message: 'Internal Server Error', code: constants.ERROR_CODES.INTERNAL_SERVER_ERROR },
  ) {
    super(error.message);

    Object.setPrototypeOf(this, ServerException.prototype);
  }

  serializeErrors() {
    return [{ ...this.error }];
  }
}

class Constant {
  private _ERROR_CODES = {
    DATA_ALREADY_EXIST: 'DATA_ALREADY_EXIST',
    INVALID_VALUES: 'INVALID_VALUES',
    INVALID_DATA: 'INVALID_DATA',
    OUT_OF_RANGE: 'OUT_OF_RANGE',
    DATA_HAS_REFERENCE: 'DATA_HAS_REFERENCE',
    INTERNAL_SERVER_ERROR: 'INTERNAL_SERVER_ERROR',
    NOT_FOUND: 'NOT_FOUND',
    UNAUTHORIZED: 'UNAUTHORIZED',
    BAD_REQUEST: 'BAD_REQUEST',
    FORBIDDEN: 'FORBIDDEN',
  };

  private _HTTP_STATUS_CODES = {
    BAD_REQUEST: 400,
    UNAUTHORIZED: 401,
    FORBIDDEN: 403,
    NOT_FOUND: 404,
    CONFLICT: 409,
    INTERNAL_SERVER_ERROR: 500,
  };

  get HTTP_STATUS_CODES() {
    return this._HTTP_STATUS_CODES;
  }

  get ERROR_CODES() {
    return this._ERROR_CODES;
  }
}

export default new Constant();

import { BaseException } from '../exceptions/base-exception';
import { ForeignKeyViolationException } from './exceptions/sql-exceptions/foreign-key-violation-exception';
import objectionDBExceptionParser from './objectionjs-parser';
import { lazyLoad } from '../utils/helper';

export function isSequelizeError(error: unknown) {
  const sequelize = lazyLoad('sequelize');
  return error instanceof sequelize.BaseError;
}

export default function sequelizeDBExceptionParser(err: any): BaseException | null {
  const sequelize = lazyLoad('sequelize');
  if (err instanceof sequelize.UniqueConstraintError) {
    return objectionDBExceptionParser(err.original);
  }

  if (err instanceof sequelize.ForeignKeyConstraintError) {
    const constraint = err?.index || '';
    return new ForeignKeyViolationException(constraint, err?.original);
  }
  if (err instanceof sequelize.DatabaseError) {
    return objectionDBExceptionParser(err.original);
  }

  return null;
}

import { SQLDatabaseException } from './sql-database-exception';
import constants from '../../../utils/constants';

function isReferenceError(nativeError: any) {
  const stillReferencedInAnotherTableReg = new RegExp(/Key \(.+\)=\(.+\) is still referenced from table ".+"\./);
  return stillReferencedInAnotherTableReg.test(nativeError?.detail) || nativeError?.errno == 1451;
}

function isHasNoReferenceError(nativeError: any) {
  const notExistInAnotherTableReg = new RegExp(/^Key \(.+\)=\(.+\) is not present in table ".+"\.$/);
  return notExistInAnotherTableReg.test(nativeError?.detail) || nativeError?.errno == 1452;
}

function extractDetails(constraint: string, nativeError: any) {
  if (isHasNoReferenceError(nativeError)) {
    return [
      {
        code: constants.ERROR_CODES.INVALID_DATA,
        message: `Invalid data`,
        details: {
          reason: 'violates foreign key constraint',
          constraint: constraint,
        },
      },
    ];
  } else if (isReferenceError(nativeError)) {
    return [
      {
        code: constants.ERROR_CODES.DATA_HAS_REFERENCE,
        message: `Data has reference`,
        details: {
          reason: 'violates foreign key constraint',
          constraint: constraint,
        },
      },
    ];
  } else {
    return [
      {
        code: constants.ERROR_CODES.INVALID_DATA,
        message: `Invalid data`,
        details: {
          reason: 'violates foreign key constraint',
          constraint: constraint,
        },
      },
    ];
  }
}

