export function lazyLoad(moduleName: string, importError?: string) {
  try {
    return require(moduleName);
  } catch (e) {
    if (importError) {
      throw new Error(importError);
    } else if (importErrors[moduleName]) {
      throw new Error(importErrors[moduleName]);
    }
  }
}

